import numpy as np

def feature(item, bins, capacity):
    """col0 = 1.0 only for the last (new empty) bin, else 0.0; col1 = (bins - mean(bins)) / capacity, with the mean taken over open bins only (excluding the new empty bin)."""
    bins = np.asarray(bins, dtype=float)
    k = bins.shape[0]
    col0 = np.zeros(k, dtype=float)
    if k > 0:
        col0[-1] = 1.0
    # Mean room over the existing open bins only; the brand-new bin is priced by col0,
    # so it should not drag the reference room upward.
    if k > 1:
        mean_room = bins[:-1].mean()
    elif k == 1:
        mean_room = bins[0]
    else:
        mean_room = 0.0
    col1 = (bins - mean_room) / float(capacity)
    return np.stack([col0, col1], axis=1)

import numpy as np

def feature(item, bins, capacity):
    """Remaining room of each candidate bin (normalised by capacity), with the new empty bin pinned to the mean room of the open bins."""
    room = bins.astype(float) / float(capacity)
    val = room.copy()
    if bins.shape[0] > 1:
        val[-1] = np.mean(room[:-1])
    else:
        val[-1] = 0.5
    return np.clip(val, -1.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """1.0 if the bin fits the item and its post-placement residual is at most 3% of capacity, else 0.0."""
    room = np.asarray(bins, dtype=float)
    r = (room - item) / float(capacity)
    return np.where(room >= item, (r <= 0.03).astype(float), 0.0)

import numpy as np

def feature(item, bins, capacity):
    """Normalised position of each candidate in the oldest-first lineup: pos/(k-1), 0 for the oldest, 1 for the new bin."""
    k = bins.shape[0]
    if k <= 1:
        return np.zeros(k, dtype=float)
    return np.arange(k, dtype=float) / (k - 1)
